// KAT gate for LuckyHash difficulty (doc 05 §5.3.1). Expected values were
// generated by the Rust reference (`lm-pow`) and are pinned byte-exact.
// Build & run: verus/src/crypto/lucky_kat.sh (runs both gates).

#include "crypto/lucky_difficulty.h"
#include "uint256.h"

// Stand-in for utilstrencodings' HexDigit: uint256.cpp (linked for base_uint
// Roundtrip support) references it via base_blob::SetHex, which these gates
// never exercise. Kept trivial and local to the standalone KAT runner.
signed char HexDigit(char c)
{
    if (c >= '0' && c <= '9') return (signed char)(c - '0');
    if (c >= 'a' && c <= 'f') return (signed char)(c - 'a' + 10);
    if (c >= 'A' && c <= 'F') return (signed char)(c - 'A' + 10);
    return -1;
}

#include <stdio.h>
#include <string.h>
#include <string>

using namespace ember;

static int failures = 0;

static std::string HexOf(const arith_uint256 &v)
{
    uint256 u = ArithToUint256(v);
    std::string s;
    s.reserve(64);
    char b[3];
    for (int i = 31; i >= 0; i--)
    {
        snprintf(b, sizeof(b), "%02x", u.begin()[i]);
        s += b;
    }
    return s;
}

static void check(const char *name, const arith_uint256 &got, const char *want_hex)
{
    std::string g = HexOf(got);
    if (g != want_hex)
    {
        failures++;
        printf("FAIL %s\n  got  %s\n  want %s\n", name, g.c_str(), want_hex);
    }
    else
    {
        printf("ok   %s\n", name);
    }
}

int main()
{
    const arith_uint256 g = arith_uint256(1) << 220;

    arith_uint256 targets[LWMA_N];
    int64_t times[LWMA_N + 1];

    // V1: steady 60 s solvetimes -> fixed point at 2^220.
    {
        for (int i = 0; i < (int)LWMA_N; i++) targets[i] = g;
        for (int i = 0; i <= (int)LWMA_N; i++) times[i] = (int64_t)i * 60;
        arith_uint256 next;
        if (!LwmaNextTarget(next, targets, LWMA_N, times, LWMA_N + 1)) { failures++; }
        check("V1 steady-state 2^220", next, "0000000010000000000000000000000000000000000000000000000000000000");
    }

    // V2: 2x slow -> clamped to last + last/3.
    {
        for (int i = 0; i <= (int)LWMA_N; i++) times[i] = (int64_t)i * 120;
        arith_uint256 next;
        LwmaNextTarget(next, targets, LWMA_N, times, LWMA_N + 1);
        check("V2 +33% clamp      ", next, "0000000015555555555555555555555555555555555555555555555555555555");
        check("V2 == g + g/3      ", next, HexOf(g + g / 3).c_str());
    }

    // V3: 2x fast -> clamped to last - last/3.
    {
        for (int i = 0; i <= (int)LWMA_N; i++) times[i] = (int64_t)i * 30;
        arith_uint256 next;
        LwmaNextTarget(next, targets, LWMA_N, times, LWMA_N + 1);
        check("V3 -33% clamp      ", next, "000000000aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab");
        check("V3 == g - g/3      ", next, HexOf(g - g / 3).c_str());
    }

    // V4: ragged oracle vector.
    {
        for (int i = 0; i < (int)LWMA_N; i++)
        {
            targets[i] = g - arith_uint256((uint64_t)i) * (arith_uint256(1) << 212);
        }
        for (int i = 0; i <= (int)LWMA_N; i++) times[i] = (int64_t)i * 60 + (int64_t)(i % 7) * 13;
        arith_uint256 next;
        LwmaNextTarget(next, targets, LWMA_N, times, LWMA_N + 1);
        check("V4 ragged oracle   ", next, "000000000eda080ec5bfdfc4e90080ec5bfdfc4e90080ec5bfdfc4e90080ec5b");
    }

    // Zero solvetimes: raw = 0 -> exactly last - last/3.
    {
        for (int i = 0; i < (int)LWMA_N; i++) targets[i] = g;
        for (int i = 0; i <= (int)LWMA_N; i++) times[i] = 1000000;
        arith_uint256 next;
        LwmaNextTarget(next, targets, LWMA_N, times, LWMA_N + 1);
        check("zero-solvetime floor", next, HexOf(g - g / 3).c_str());
    }

    // POW_LIMIT roundtrip: compact 0x1f00ffff <-> expansion.
    {
        arith_uint256 lim = PowLimit();
        check("POW_LIMIT expansion", lim, "0000ffff00000000000000000000000000000000000000000000000000000000");
        arith_uint256 round;
        round.SetCompact(0x1f00ffffUL);
        check("0x1f00ffff decode  ", round, HexOf(lim).c_str());
        if (lim.GetCompact() != 0x1f00ffffUL)
        {
            failures++;
            printf("FAIL POW_LIMIT re-encode: got 0x%08x\n", lim.GetCompact());
        }
        else
        {
            printf("ok   POW_LIMIT re-encode 0x1f00ffff\n");
        }
    }

    // Bad lengths rejected.
    {
        arith_uint256 next;
        if (LwmaNextTarget(next, targets, LWMA_N - 1, times, LWMA_N + 1) ||
            LwmaNextTarget(next, targets, LWMA_N, times, LWMA_N))
        {
            failures++;
            printf("FAIL bad-length rejection\n");
        }
        else
        {
            printf("ok   bad lengths rejected\n");
        }
    }

    printf("\n%s (%d failures)\n", failures ? "DIFF KAT GATE FAILED" : "DIFF KAT GATE PASSED", failures);
    return failures ? 1 : 0;
}
